### messages.ts — pure conversions

```ts
// providers/llm/openai/messages.ts
import type { LLMMessage } from "../../types";
import type { OpenAIMessage } from "./types";

export function toOpenAIMessages(messages: readonly LLMMessage[]): OpenAIMessage[] {
  return messages.map((m) => {
    const role: OpenAIMessage["role"] =
      m.role === "assistant" ? "assistant" : m.role === "system" ? "system" : "user";
    const content =
      typeof m.content === "string"
        ? m.content
        : m.content.map((p) => (p.type === "text" ? p.text : "")).join("");
    return { role, content };
  });
}

export function extractContentDelta(payload: Record<string, unknown>): string | null {
  const choices = payload.choices as Array<{ delta?: { content?: string } }> | undefined;
  return choices?.[0]?.delta?.content ?? null;
}
```

### parse.ts — the shared SSE loop as `parseStreamLine`

The SSE parse loop was inlined twice in the original (non-stream + stream paths). Extracted once and shared:

```ts
// providers/llm/openai/parse.ts
import { STREAM_DONE } from "./constants";

export interface SSEEvent { event: string; data: string }

/** Parse a single SSE line; returns null for blank/comment lines. Handles CRLF. */
export function parseStreamLine(line: string): SSEEvent | null {
  const text = line.endsWith("\r") ? line.slice(0, -1) : line; // SSE spec allows CRLF
  if (text === "" || text.startsWith(":")) return null;        // comment / keep-alive
  const colon = text.indexOf(":");
  const field = colon === -1 ? text : text.slice(0, colon);
  let value = colon === -1 ? "" : text.slice(colon + 1);
  if (value.startsWith(" ")) value = value.slice(1);           // "data: x" vs "data:x"
  return { event: field, data: value };
}

/** Shared loop: buffers partial lines across chunks, yields parsed JSON, stops at [DONE]. */
export async function* parseSSEStream(
  chunks: AsyncIterable<string>,
  signal?: AbortSignal,
): AsyncGenerator<Record<string, unknown>> {
  let buffer = "";
  const flush = (line: string) => {
    const evt = parseStreamLine(line);
    if (!evt || evt.event !== "data") return null;
    if (evt.data === STREAM_DONE) return "done";
    try { return JSON.parse(evt.data) as Record<string, unknown>; }
    catch { return null; } // malformed keep-alive payload → ignore
  };
  for await (const chunk of chunks) {
    if (signal?.aborted) return;
    buffer += chunk;
    let nl: number;
    while ((nl = buffer.indexOf("\n")) !== -1) {
      const line = buffer.slice(0, nl);
      buffer = buffer.slice(nl + 1);
      const out = flush(line);
      if (out === "done") return;
      if (out) yield out;
    }
  }
  if (buffer) {                       // flush trailing partial line at EOF
    const out = flush(buffer);
    if (out && out !== "done") yield out;
  }
}
```

### http.ts — transport

```ts
// providers/llm/openai/http.ts
import { DEFAULT_BASE_URL, DEFAULT_TIMEOUT_MS } from "./constants";
import { parseSSEStream } from "./parse";

export interface OpenAIHttpOptions {
  apiKey: string;
  baseUrl?: string;
  timeoutMs?: number;
}

export function authHeaders(apiKey: string): Record<string, string> {
  return { Authorization: `Bearer ${apiKey}`, "Content-Type": "application/json" };
}

export class OpenAIHttpError extends Error {
  constructor(readonly status: number, readonly body: string) {
    super(`OpenAI API error ${status}: ${body}`);
    this.name = "OpenAIHttpError";
  }
}

export async function postJSON<T>(path: string, body: unknown, opts: OpenAIHttpOptions): Promise<T> {
  const ctrl = new AbortController();
  const timer = setTimeout(() => ctrl.abort(), opts.timeoutMs ?? DEFAULT_TIMEOUT_MS);
  try {
    const res = await fetch(`${opts.baseUrl ?? DEFAULT_BASE_URL}${path}`, {
      method: "POST", headers: authHeaders(opts.apiKey), body: JSON.stringify(body), signal: ctrl.signal,
    });
    if (!res.ok) throw new OpenAIHttpError(res.status, await res.text());
    return (await res.json()) as T;
  } finally {
    clearTimeout(timer);
  }
}

export async function* streamJSON(
  path: string, body: unknown, opts: OpenAIHttpOptions,
): AsyncGenerator<Record<string, unknown>> {
  const res = await fetch(`${opts.baseUrl ?? DEFAULT_BASE_URL}${path}`, {
    method: "POST", headers: authHeaders(opts.apiKey), body: JSON.stringify(body),
  });
  if (!res.ok) throw new OpenAIHttpError(res.status, await res.text());
  if (!res.body) throw new Error("OpenAI stream: response body is null");
  const reader = res.body.getReader();
  const decoder = new TextDecoder();
  const strings = (async function* () {
    for (;;) {
      const { done, value } = await reader.read();
      if (done) return;
      yield decoder.decode(value, { stream: true });
    }
  })();
  yield* parseSSEStream(strings);
}
```

### core.ts — class + factory + the two side effects

```ts
// providers/llm/openai/core.ts
import {
  type LLMChatOptions, type LLMResult, type LLMStreamChunk, type LLMProvider,
  registerLLMProvider, llmProviderRegistry,
} from "../../registry";
import {
  DEFAULT_BASE_URL, DEFAULT_MAX_TOKENS, DEFAULT_TEMPERATURE, SUPPORTED_MODELS,
} from "./constants";
import { extractContentDelta, toOpenAIMessages } from "./messages";
import { postJSON, streamJSON } from "./http";
import type { OpenAIChatRequest, OpenAIChatResponse } from "./types";

export interface OpenAIProviderOptions {
  apiKey?: string;
  baseUrl?: string;
  model?: string;
}

export class OpenAIProvider implements LLMProvider {
  readonly id = "openai";
  readonly name = "OpenAI";
  readonly supportedModels = SUPPORTED_MODELS;

  private readonly apiKey: string;
  private readonly baseUrl: string;
  private readonly model: string;

  constructor(options: OpenAIProviderOptions = {}) {
    this.apiKey = options.apiKey ?? process.env.OPENAI_API_KEY ?? "";
    if (!this.apiKey) throw new Error("OpenAIProvider: OPENAI_API_KEY is required");
    this.baseUrl = options.baseUrl ?? DEFAULT_BASE_URL;
    this.model = options.model ?? SUPPORTED_MODELS[0];
  }

  async chat(messages: readonly LLMMessage[], opts: LLMChatOptions = {}): Promise<LLMResult> {
    const body: OpenAIChatRequest = {
      model: opts.model ?? this.model,
      messages: toOpenAIMessages(messages),
      max_tokens: opts.maxTokens ?? DEFAULT_MAX_TOKENS,
      temperature: opts.temperature ?? DEFAULT_TEMPERATURE,
    };
    const res = await postJSON<OpenAIChatResponse>("/chat/completions", body, {
      apiKey: this.apiKey, baseUrl: this.baseUrl,
    });
    return { id: res.id, text: res.choices[0]?.message.content ?? "", usage: res.usage };
  }

  async *stream(messages: readonly LLMMessage[], opts: LLMChatOptions = {}): AsyncGenerator<LLMStreamChunk> {
    const body: OpenAIChatRequest = {
      model: opts.model ?? this.model,
      messages: toOpenAIMessages(messages),
      max_tokens: opts.maxTokens ?? DEFAULT_MAX_TOKENS,
      temperature: opts.temperature ?? DEFAULT_TEMPERATURE,
      stream: true,
    };
    for await (const payload of streamJSON("/chat/completions", body, {
      apiKey: this.apiKey, baseUrl: this.baseUrl,
    })) {
      const delta = extractContentDelta(payload);
      if (delta) yield { type: "delta", text: delta };
    }
  }
}

export function createOpenAI(options?: OpenAIProviderOptions): OpenAIProvider {
  return new OpenAIProvider(options);
}

// ── Module-load side effects (must stay in core.ts) ─────────────
registerLLMProvider("openai", () => createOpenAI());
llmProviderRegistry.register("openai", OpenAIProvider);
```

Both side effects move to `core.ts` (bottom of the module) — importing `constants.ts`/`parse.ts`/`types.ts` subpaths never triggers registration, and the registry is populated exactly once via the barrel.
